package dailypractice;

public class Swap02 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num1=20;
		int num2=15;
		
		num1=num1+num2;  //35
		num2=num1-num2;  //20
		num1=num1-num2;  //15
		System.out.println("num1:"+num1);
		System.out.println("num2:"+num2);

	}

}
